// EchoMind English - Phase 5 Knowledge Base (Days 81 - 100)
// Theme: 1314 播客核心哲學與母語直覺大腦 (1314 Core Mindset, Native Intuition & Fluency Sprints) - CEFR B1+ (200 Chunks)
// Aligned with English Podcast 1314 methodology: Short chunks (2-5 words), self-talk, muscle memory, wind down, it is what it is, progress over perfection.

(function() {
  window.ECHOMIND_PHASE_5 = {
    // Day 81: 開門見山與說到重點 (Get Straight to the Point)
    81: [
      { text: "Get straight to the point.", sit: "開門見山直接切入重點 (不繞圈子)", lit: "得到直接到那點", fast: "Straight to the point [/streɪt tə ðə pɔɪnt/]", note: "口語中常直接說 Straight to the point!", q: "Can we skip the small talk and discuss the final decision?", cefr: "B1" },
      { text: "The point is...", sit: "關鍵的重點在於... / 我想說的核心是...", lit: "那點是...", fast: "The point is [/ðə pɔɪnt ɪz/]", note: "point is 連音為 /ˈpɔɪn.tɪz/。", q: "Why did you call an urgent meeting with the whole team?", cefr: "A2" },
      { text: "What matters most is...", sit: "最至關重要的事情是...", lit: "什麼緊要最多是...", fast: "What matters most [/wʌt ˈmætərz moʊst/]", note: "引導大家聚焦在核心關鍵價值上。", q: "Should we worry about the minor formatting details on the slide?", cefr: "B1" },
      { text: "The bottom line is...", sit: "說到底，底線事實就是... (收斂結論神句)", lit: "底線是...", fast: "The bottom line is [/ðə ˈbɑːtəm laɪn ɪz/]", note: "母語者提煉結論時最高頻口頭禪。", q: "After analyzing all the travel costs, can we afford the trip?", cefr: "B1" },
      { text: "In a nutshell...", sit: "簡而言之 / 一言以蔽之...", lit: "在一個堅果殼裡...", fast: "In a nutshell [/ɪn ə ˈnʌtʃel/]", note: "把長篇大論濃縮成一句話總結。", q: "Can you summarize the main takeaway from that two-hour lecture?", cefr: "B1" },
      { text: "Cut through the noise.", sit: "撥開雜音看透問題本質", lit: "剪切穿過那噪音", fast: "Cut through the noise [/kʌt θruː ðə nɔɪz/]", note: "不被無關痛癢的次要細節分散注意力。", q: "There are so many conflicting rumors on social media!", cefr: "B1" },
      { text: "Here's the deal:", sit: "事情的情況是這樣的：(提出方案或事實)", lit: "這裡是這交易：", fast: "Here's the deal [/hɪrz ðə diːl/]", note: "美語中極其自然的開場白，引出具體方案。", q: "How are we going to split the chores fairly this week?", cefr: "A2" },
      { text: "Focus on what counts.", sit: "把精力聚焦在真正有價值的事情上", lit: "聚焦在什麼計算", fast: "Focus on what counts [/ˈfoʊkəs ɑːn wʌt kaʊnts/]", note: "counts 代表有價值、重要。", q: "I'm stressed about choosing between ten different notebook colors!", cefr: "B1" },
      { text: "Core message", sit: "最核心、最想傳遞的中心訊息", lit: "核心訊息", fast: "Core message [/kɔːr ˈmesɪdʒ/]", note: "避免說話發散不知所云。", q: "What should the audience remember after hearing your presentation?", cefr: "B1" },
      { text: "Clear and concise", sit: "表達清晰簡明扼要、乾淨俐落", lit: "清晰且簡明", fast: "Clear an' concise [/klɪr ən kənˈsaɪs/]", note: "concise 重音在第二音節 /kənˈsaɪs/。", q: "How did you manage to explain that complex recipe so fast?", cefr: "B1" }
    ],

    // Day 82: 話到嘴邊與記憶搜索 (Tip of My Tongue)
    82: [
      { text: "On the tip of my tongue!", sit: "就在我嘴邊了！一時叫不出名字！(超生動)", lit: "在我的舌頭的尖端上！", fast: "On the tip of my tongue [/ɑːn ðə tɪp əv maɪ tʌŋ/]", note: "tip of 連音為 /ˈtɪ.pəv/，想得起長相叫不出名字時說。", q: "What was the name of that charming Italian cafe by the park?", cefr: "A2" },
      { text: "It completely slipped my mind.", sit: "我一時完全給忘了 / 腦袋徹底遺漏了", lit: "它完全滑落了我的心智", fast: "Slipped my mind [/slɪpt maɪ maɪnd/]", note: "委婉承認自己忘記事情的高情商表達。", q: "Did you remember to pick up the dry cleaning this morning?", cefr: "B1" },
      { text: "Does that ring a bell?", sit: "這聽起來有讓你聯想起什麼嗎？有印象嗎？", lit: "做那個搖響一個鈴鐺嗎？", fast: "Ring a bell? [/rɪŋ ə bel/]", note: "確認對方是否對某人事物有模糊印象。", q: "We met a guy named Marcus in Amsterdam three years ago.", cefr: "A2" },
      { text: "It'll come to me.", sit: "別急，我待會兒就會想起來的", lit: "它將會來到我", fast: "It'll come to me [/ˈɪtl kʌm tə miː/]", note: "叫大家別提示，給自己一點回想空間。", q: "Do you need me to look up that movie actor on Google?", cefr: "B1" },
      { text: "I'm drawing a blank.", sit: "我腦袋現在一片空白，想不起來", lit: "我正畫著一個空白", fast: "Drawin' a blank [/ˈdrɔːɪn ə blæŋk/]", note: "形容被突然點名發問時大腦當機。", q: "What was our Wi-Fi router password before we changed it?", cefr: "B1" },
      { text: "My mind went blank.", sit: "我的大腦剛才突然完全一片空白", lit: "我的心智去了空白", fast: "Mind went blank [/maɪnd went blæŋk/]", note: "過去時態，自嘲緊張時的空白片刻。", q: "Why did you pause for five seconds during your introduction?", cefr: "A2" },
      { text: "What's his name again?", sit: "他叫什麼名字來著？(再次確認)", lit: "什麼是他的名字再次？", fast: "What's his name again? [/wʌts ɪz neɪm əˈɡen/]", note: "his 的 h 常常弱讀吞音成 /ɪz/。", q: "You just bumped into your former high school math teacher!", cefr: "A2" },
      { text: "It just hit me!", sit: "我突然想起來了！靈光一閃！", lit: "它剛好擊打我！", fast: "It just hit me! [/ɪt dʒʌst hɪt miː/]", note: "靈感或記憶突然湧現時的興奮感嘆。", q: "Did you finally remember where you parked your car at the mall?", cefr: "A2" },
      { text: "Refresh my memory.", sit: "幫我重新喚醒一下記憶 / 給我個提示吧", lit: "刷新我的記憶", fast: "Refresh my memory [/rɪˈfreʃ maɪ ˈmeməri/]", note: "禮貌請對方提供背景脈絡。", q: "Do you recall the details of our agreement from last month?", cefr: "B1" },
      { text: "Lost my train of thought.", sit: "我剛才把說話的思緒給弄斷了", lit: "丟失了我的思想的火車", fast: "Lost my train of thought [/lɔːst maɪ treɪn əv/]", note: "train of 連音為 /ˈtreɪ.nəv/，被打斷時常用。", q: "Where were you heading with that story before the dog barked?", cefr: "B1" }
    ],

    // Day 83: 隨機應變與見機行事 (Play It by Ear)
    83: [
      { text: "Play it by ear.", sit: "隨機應變 / 到時候看情況行事 (極高頻生活俚語)", lit: "玩它藉由耳朵", fast: "Play it by ear [/pleɪ ɪt baɪ ɪr/]", note: "源自不看樂譜純靠耳朵聽音即興演奏的智慧。", q: "What's our exact schedule after we land in Tokyo?", cefr: "B1" },
      { text: "See how it goes.", sit: "走著瞧，看看後續情況如何再做打算", lit: "看如何它走", fast: "See how it goes [/siː haʊ ɪt ɡoʊz/]", note: "不把未來的安排定死，保持彈性。", q: "Are you going to stay at the party all night?", cefr: "A2" },
      { text: "Cross that bridge later.", sit: "船到橋頭自然直，到時候碰上了再說", lit: "穿過那座橋稍後", fast: "Cross that bridge later [/krɔːs ðæt brɪdʒ/]", note: "不為還沒發生的潛在問題預支焦慮。", q: "What if it rains on the day of our outdoor barbecue next month?", cefr: "B1" },
      { text: "Keep our options open.", sit: "保留各種可能性與後路，不把話說死", lit: "保持我們選項打開", fast: "Options open [/ˈɑːpʃnz ˈoʊpən/]", note: "做決策時留有餘地的高手策略。", q: "Should we book non-refundable train tickets right now?", cefr: "B1" },
      { text: "Wing it!", sit: "即興發揮！直接硬上！不擬定死板稿子！", lit: "翅膀它！", fast: "Wing it! [/wɪŋ ɪt/]", note: "wing it 連讀為 /ˈwɪ.ŋɪt/，臨場自由發揮。", q: "Did you prepare a scripted speech for tonight's toast?", cefr: "B1" },
      { text: "Go with the flow.", sit: "順應大自然的節奏變化，隨遇而安 (1314 鬆弛感)", lit: "走隨著那流動", fast: "Go with the flow [/ɡoʊ wɪð ðə floʊ/]", note: "人生最好的生活態度：不對抗，順流而行。", q: "The museum was closed, so we ended up exploring a hidden street market!", cefr: "A2" },
      { text: "Stay flexible.", sit: "保持高度的彈性與靈活適應力", lit: "停留靈活的", fast: "Stay flexible [/steɪ ˈfleksəbl/]", note: "旅行或生活中面對突發狀況的必備心理素質。", q: "Flight delays and subway strikes can happen at any time.", cefr: "B1" },
      { text: "Take it as it comes.", sit: "泰然處之，事情來了就兵來將擋水來土掩", lit: "拿取它如同它來", fast: "Take it as it comes [/teɪk ɪt æz ɪt kʌmz/]", note: "平靜迎接生活中的各種偶發事件。", q: "How do you handle having an unpredictable daily schedule?", cefr: "B1" },
      { text: "Adapt to the moment.", sit: "根據當下的具體局勢靈活調整對策", lit: "適應對這時刻", fast: "Adapt to the moment [/əˈdæpt tə ðə ˈmoʊmənt/]", note: "adapt to 連讀為 /əˈdæp.tə/。", q: "The restaurant ran out of pasta, so we ordered pizza instead.", cefr: "B1" },
      { text: "No rigid plans.", sit: "不給自己設定死板僵化的硬性計畫", lit: "沒有剛硬的計畫", fast: "No rigid plans [/noʊ ˈrɪdʒɪd plænz/]", note: "rigid 表示死板不變通的。", q: "Do you have a minute-by-minute itinerary for our road trip?", cefr: "B1" }
    ],

    // Day 84: 豁達大度與釋懷看開 (No Hard Feelings & Moving On)
    84: [
      { text: "No hard feelings at all.", sit: "完全不記仇！大家依然是好朋友 (1314 招牌心態)", lit: "沒有硬感覺在全部", fast: "No hard feelings [/noʊ hɑːrd ˈfiːlɪŋz ət ɔːl/]", note: "競爭結束或坦誠說開後的大度宣告。", q: "I'm so glad we competed for the same role and stayed friends!", cefr: "B1" },
      { text: "Don't take it personally.", sit: "別太往心裡去，這純粹對事不對人", lit: "不要拿取它個人地", fast: "Don't take it personally [/doʊnt teɪk ɪt ˈpɜːrsənəli/]", note: "安慰受挫朋友不要自我懷疑的名言。", q: "They decided to go with another design prototype instead of mine.", cefr: "B1" },
      { text: "All in good fun.", sit: "大家開開玩笑，純屬娛樂消遣，別當真", lit: "全部在好樂趣中", fast: "All in good fun [/ɔːl ɪn ɡʊd fʌn/]", note: "互相開玩笑後化解尷尬的常用語句。", q: "Did Alex really mean it when he teased your cooking skills?", cefr: "A2" },
      { text: "Shake it off!", sit: "甩掉負能量！把不順心通通抖掉！(泰勒斯名言)", lit: "搖晃它脫離！", fast: "Shake it off! [/ʃeɪk ɪt ɔːf/]", note: "shake it off 三字連讀為 /ˈʃeɪ.kɪ.tɔːf/。", q: "I tripped on the sidewalk and a few people looked at me.", cefr: "A2" },
      { text: "Time to move on.", sit: "是時候放下過去，大步向前邁進了", lit: "時間去移動在上面", fast: "Time ta move on [/taɪm tə muːv ɑːn/]", note: "move on 連音為 /ˈmuː.vɑːn/，向過去告別。", q: "I've been dwelling on that failed exam for two whole weeks.", cefr: "A2" },
      { text: "Let bygones be bygones.", sit: "既往不咎，一笑泯恩仇 / 讓過去的隨風去", lit: "讓過去者是過去者", fast: "Bygones be bygones [/ˈbaɪɡɔːnz biː ˈbaɪɡɔːnz/]", note: "大器原諒舊日的恩恩怨怨。", q: "Can we finally bury our differences and celebrate the holidays together?", cefr: "B1" },
      { text: "No grudges held.", sit: "心中絕不存留任何一絲怨恨或疙瘩", lit: "沒有怨恨被持有", fast: "No grudges [/noʊ ˈɡrʌdʒɪz held/]", note: "grudge 表示懷恨、記仇。", q: "Are you still angry about what happened three years ago?", cefr: "B1" },
      { text: "Water under the bridge.", sit: "過去的就讓它如流水般逝去吧 / 往事已矣", lit: "水在橋樑底下", fast: "Water under the bridge [/ˈwɔːtər ˈʌndər ðə brɪdʒ/]", note: "經典的英語原諒放下成語。", q: "Thank you for forgiving me for losing that vintage book.", cefr: "B1" },
      { text: "Hold your head high.", sit: "昂首挺胸！問心無愧！自信面對！", lit: "保持你的頭高", fast: "Hold yer head high [/hoʊld jər hed haɪ/]", note: "即便失敗也昂首挺胸的尊嚴風骨。", q: "We didn't win first place, but we gave it our absolute best effort.", cefr: "B1" },
      { text: "Inner peace over winning", sit: "內心的平靜安詳，遠勝過無謂的口舌爭吵輸贏", lit: "內在和平在贏過", fast: "Inner peace [/ˈɪnər piːs ˈoʊvər ˈwɪnɪŋ/]", note: "成熟智慧的人生取捨境界。", q: "Why did you choose not to argue back with that rude commenter?", cefr: "B1" }
    ],

    // Day 85: 見好就收與劃下句點 (Call It a Day)
    85: [
      { text: "Let's call it a day.", sit: "今天就先到這裡吧！收工下班！(母語者下班金句)", lit: "讓我們稱呼它一個天", fast: "Call it a day [/kɔːl ɪt ə deɪ/]", note: "call it a 連讀為 /ˈkɔː.lɪ.tə/，宣布今天工作圓滿結束。", q: "It's 6 PM and we finished all thirty customer support tickets!", cefr: "A2" },
      { text: "Wrap things up now.", sit: "現在把手頭上的事情做個收尾打烊吧", lit: "包裹事情向上現在", fast: "Wrap things up [/ræp θɪŋz ʌp naʊ/]", note: "wrap up 連音為 /ˈræ.pʌp/。", q: "The restaurant closes in fifteen minutes, team!", cefr: "B1" },
      { text: "That's a wrap!", sit: "順利收官殺青！大功告成！全數搞定！", lit: "那是包裹！", fast: "That's a wrap! [/ðæts ə ræp/]", note: "源自拍電影導演喊卡收鏡頭的殺青口令。", q: "We recorded all ten podcast episodes for this season!", cefr: "B1" },
      { text: "Time to head home.", sit: "該是動身收拾回家的時候了", lit: "時間去頭朝家", fast: "Head home [/hed hoʊm/]", note: "收拾桌面包包準備走人。", q: "Look at the clock, it's already dark outside the window.", cefr: "A2" },
      { text: "End on a high note.", sit: "在最美好的高潮氣氛下畫下句點", lit: "結束在一個高音符上", fast: "High note [/haɪ noʊt/]", note: "見好就收，留下最美好的回憶與餘韻。", q: "That last karaoke song had everyone standing and cheering!", cefr: "B1" },
      { text: "Shut down the laptop.", sit: "把筆記型電腦關機闔上 (1314 下班儀式)", lit: "關閉向下那筆記型電腦", fast: "Shut down the laptop [/ʃʌt daʊn ðə ˈlæptɑːp/]", note: "實質下班的標誌性儀式動作。", q: "How do you signal to your brain that the workday is officially over?", cefr: "A2" },
      { text: "Pack up our bags.", sit: "收拾好我們的背包準備離開", lit: "打包向上我們的背包", fast: "Pack up our bags [/pæk ʌp ˈaʊər bæɡz/]", note: "pack up 連音為 /ˈpæ.kʌp/。", q: "The library lights are flickering to signal closing time.", cefr: "A2" },
      { text: "Leave work at work.", sit: "把工作留在辦公室，下班絕不帶回家煩惱", lit: "離開工作在工作", fast: "Leave work at work [/liːv wɜːrk æt wɜːrk/]", note: "工作與生活平衡的最健康分界線。", q: "What's the golden rule for protecting your evening peace of mind?", cefr: "B1" },
      { text: "Good day's work", sit: "辛勤充實的一天付出與辛勞", lit: "好天的工作", fast: "Good day's work [/ɡʊd deɪz wɜːrk/]", note: "自我肯定今天充實的付出。", q: "We painted the entire fence and mowed the lawn today!", cefr: "A2" },
      { text: "Rest up for tomorrow.", sit: "今晚好好休息充電，迎接明天的嶄新挑戰", lit: "休息向上為了明天", fast: "Rest up [/rest ʌp fər təˈmɔːroʊ/]", note: "rest up 連讀成 /ˈres.tʌp/。", q: "Good night everyone, see you all at nine tomorrow morning!", cefr: "A2" }
    ],

    // Day 86: 接受現實的鬆弛感 (It Is What It Is - 1314 靈魂哲學)
    86: [
      { text: "It is what it is.", sit: "既成事實，木已成舟 / 看開點吧 (1314 靈魂名言)", lit: "它是什麼它是", fast: "It is what it is [/ɪt ɪz wʌt ɪt ɪz/]", note: "全然接納客觀不可抗力，毫無內耗自責。", q: "The thunderstorm knocked out power and our outdoor grill dinner is canceled.", cefr: "A2" },
      { text: "Such is life.", sit: "人生不如意十之八九，世事往往如此", lit: "如此是生命", fast: "Such is life [/sʌtʃ ɪz laɪf/]", note: "such is 連讀為 /ˈsʌ.tʃɪz/，優雅看淡風雲。", q: "I dropped my sandwich right as I was about to take the first bite!", cefr: "B1" },
      { text: "Nothing we can do now.", sit: "事已至此，我們現在能做的也只有放寬心了", lit: "沒有什麼我們能做現在", fast: "Nothin' we can do [/ˈnʌθɪn wiː kən duː naʊ/]", note: "承認人類能力的極限，不跟現實較勁。", q: "The traffic is completely deadlocked on the highway.", cefr: "A2" },
      { text: "Make the best of it.", sit: "在既有的不完美條件下做到最好、自得其樂", lit: "製造那最好之它", fast: "Make the best of it [/meɪk ðə best əv ɪt/]", note: "best of it 連讀為 /ˈbes.tə.vɪt/。", q: "Our hotel room doesn't have a sea view, but the bed is super comfy!", cefr: "B1" },
      { text: "Roll with the punches.", sit: "兵來將擋，逆來順受適應各種意料之外的變化", lit: "滾動隨著那些拳擊", fast: "Roll with the punches [/roʊl wɪð ðə ˈpʌntʃɪz/]", note: "拳擊智慧：化解衝擊，保持身體平衡與韌性。", q: "Our flight was diverted to another airport due to heavy fog.", cefr: "B1" },
      { text: "Control what you can.", sit: "專注把精力放在自己真正能掌控的事情上", lit: "控制什麼你能", fast: "Control what ya can [/kənˈtroʊl wʌt jə kən/]", note: "斯多葛哲學生活智慧核心。", q: "I'm stressing out about the global economy and stock prices!", cefr: "B1" },
      { text: "Let go of the rest.", sit: "其餘無法掌控的事情就隨它去吧，別操心", lit: "讓走之那其餘", fast: "Let go of the rest [/let ɡoʊ əv ðə rest/]", note: "放手是消除焦慮的不二法門。", q: "I prepared everything for my presentation, but I'm still nervous about the audience.", cefr: "B1" },
      { text: "Accept the reality.", sit: "坦然面對並接納真實客觀的現實", lit: "接受那現實", fast: "Accept reality [/əkˈsept riˈæləti/]", note: "不自欺欺人，從現實出發。", q: "We didn't win the competition, but we learned so much from participating.", cefr: "B1" },
      { text: "Serenity in chaos", sit: "在混亂動盪的周遭環境中保有內心的平靜祥和", lit: "寧靜在混亂中", fast: "Serenity in chaos [/səˈrenəti ɪn ˈkeɪɑːs/]", note: "chaos 發音為 /ˈkeɪɑːs/。", q: "How do you remain so calm in the middle of a noisy train terminal?", cefr: "B1" },
      { text: "Peaceful acceptance", sit: "平靜安詳地全然接納生活的本來面貌", lit: "和平的接受", fast: "Peaceful acceptance [/ˈpiːsfʊl əkˈseptəns/]", note: "心靈不再與生活發生無謂的衝突摩擦。", q: "What is the ultimate definition of emotional maturity for you?", cefr: "B1" }
    ],

    // Day 87: 口腔肌肉與聲音記憶 (Muscle Memory & Shadowing - 1314 招牌特訓)
    87: [
      { text: "Oral muscle memory", sit: "建立口腔發音肌肉記憶 (English Podcast 1314 核心)", lit: "口腔肌肉記憶", fast: "Muscle memory [/ˈmʌsl ˈmeməri/]", note: "每天開口跟讀，讓嘴唇舌頭形成自然的運動記憶。", q: "Why is spoken English fundamentally a physical motor skill?", cefr: "A2" },
      { text: "Shadowing flow", sit: "影子跟讀時行雲流水般的自然流暢節奏感", lit: "影子流動", fast: "Shadowing flow [/ˈʃædoʊɪŋ floʊ/]", note: "邊聽邊跟，時差半秒，不經思考直接輸出。", q: "How does it feel when you shadow native podcast dialogues effortlessly?", cefr: "B1" },
      { text: "Mouth movement matters.", sit: "嘴唇嘴型與舌頭的發音位置至關重要", lit: "嘴運動緊要", fast: "Mouth movement matters [/maʊθ ˈmuːvmənt ˈmætərz/]", note: "改善台式發音第一步：放開嘴巴做足嘴型動作。", q: "Why do my jaw muscles feel sore after twenty minutes of practice?", cefr: "B1" },
      { text: "Repeat out loud.", sit: "大聲朗讀重複，讓自己的耳朵親耳聽見發音", lit: "重複出大聲", fast: "Repeat out loud [/rɪˈpiːt aʊt laʊd/]", note: "默讀不算練習，出聲才是真正的神經刺激。", q: "Can I just read these ten chunks silently in my bedroom?", cefr: "A2" },
      { text: "Sound natural and effortless.", sit: "說起英語聽起來自然道地、毫不費力", lit: "聽起來自然且不費力", fast: "Natural an' effortless [/ˈnætʃrəl ən ˈefərtləs/]", note: "連讀與弱讀自然結合的最高境界。", q: "What's the best compliment someone can give your English speaking?", cefr: "B1" },
      { text: "Untie your tongue.", sit: "解開舌頭的緊繃束縛，告別口說打結卡卡", lit: "解開你的舌頭", fast: "Untie yer tongue [/ʌnˈtaɪ jər tʌŋ/]", note: "多練習繞口短語塊，舌頭自然靈活自如。", q: "Do you still feel tongue-tied when greeting native speakers?", cefr: "B1" },
      { text: "Match the intonation.", sit: "模仿母語人士語調的起伏抑揚頓挫", lit: "匹配那語調", fast: "Match the intonation [/mætʃ ðə ˌɪntəˈneɪʃn/]", note: "語調比單純的個別單字音標更能傳達母語靈魂。", q: "Why does mimicking English voice melody make sentences sound so lively?", cefr: "B1" },
      { text: "Vocal cords engaged", sit: "聲帶自然振動共鳴，告別扁平微弱的氣音", lit: "聲帶被參與", fast: "Vocal cords engaged [/ˈvoʊkl kɔːrdz ɪnˈɡeɪdʒd/]", note: "英文發音位置較靠胸腔與喉部深處。", q: "How did your voice project with so much more authority today?", cefr: "B1" },
      { text: "Rhythm over grammar", sit: "自然的口語韻律節奏，重要性遠勝過死板文法 (1314 心法)", lit: "節奏在文法之上", fast: "Rhythm over grammar [/ˈrɪðəm ˈoʊvər ˈɡræmər/]", note: "只要說話有母語節拍，哪怕小文法瑕疵對方也能秒懂。", q: "What matters more when ordering food at a busy NYC diner?", cefr: "B1" },
      { text: "Speak with your breath.", sit: "用腹部均勻的深沉氣息發聲，講話更有底氣", lit: "說話帶著你的呼吸", fast: "Speak with yer breath [/spiːk wɪð jər breθ/]", note: "深沉穩定的氣流帶動連音流暢輸出。", q: "How do professional actors and broadcasters speak so tirelessly?", cefr: "B1" }
    ],

    // Day 88: 自我對話與英文思考 (Self-Talk & Thinking in English - 1314 招牌)
    88: [
      { text: "Self-talk in English", sit: "用英文自言自語自我對話 (English Podcast 1314 招牌技巧)", lit: "自我說話在英語中", fast: "Self-talk in English [/ˈself tɔːk ɪn ˈɪŋɡlɪʃ/]", note: "一個人獨處時最好的零成本口說特訓法。", q: "How can I practice speaking English if I don't have a native tutor?", cefr: "A2" },
      { text: "Think in English directly.", sit: "直接用英文塊狀思考，跳過中翻英中繼站", lit: "思考在英語中直接地", fast: "Think in English [/θɪŋk ɪn ˈɪŋɡlɪʃ dəˈrektli/]", note: "直覺大腦養成的根本秘訣。", q: "What is the biggest difference between fluent speakers and beginners?", cefr: "B1" },
      { text: "No mental translation", sit: "大腦徹底告別逐字中翻英的翻譯病", lit: "沒有心理翻譯", fast: "No translation [/noʊ trænzˈleɪʃn/]", note: "大腦思緒與口腔發音直接連通。", q: "How do you respond within 0.3 seconds when someone greets you?", cefr: "B1" },
      { text: "Inner English monologue", sit: "在大腦裡用英文展開內心獨白與思考", lit: "內在英語獨白", fast: "Inner monologue [/ˈɪnər ˈmɑːnəlɔːɡ/]", note: "逛街、做家事時腦海裡的英語背景音。", q: "What language do you think in while brewing your morning coffee?", cefr: "B1" },
      { text: "Describe your day.", sit: "隨時隨地用簡單語塊描述身邊的一天日常", lit: "描述你的一天", fast: "Describe yer day [/dɪˈskraɪb jər deɪ/]", note: "I'm cutting carrots, now boiling water... 隨處練習。", q: "How do you practice self-talk while cooking dinner in the kitchen?", cefr: "A2" },
      { text: "Talk to myself daily.", sit: "每天通勤或洗澡時對自己說英文練發音", lit: "說話對我自己每日", fast: "Talk ta myself [/tɔːk tə maɪˈself ˈdeɪli/]", note: "不用害羞害怕被別人評價嘲笑。", q: "When is your favorite time of day to practice speaking out loud?", cefr: "A2" },
      { text: "Narrate your actions.", sit: "一邊做事一邊用英文口述自己的動作 (1314 動作口述法)", lit: "敘述你的行動", fast: "Narrate yer actions [/ˈnæreɪt jər ˈækʃnz/]", note: "動詞片語與實體動作直接在大腦產生突觸連結。", q: "What's an effective way to memorize phrasal verbs like 'put on' and 'take off'?", cefr: "B1" },
      { text: "Stream of thoughts", sit: "思緒自然流動不加過濾的原汁原味想法", lit: "思想的溪流", fast: "Stream of thoughts [/striːm əv θɔːts/]", note: "不追求文法零瑕疵，專注思緒流暢湧現。", q: "What happens when you let yourself speak without censoring yourself?", cefr: "B1" },
      { text: "Instant English reaction", sit: "遇到突發狀況時的第一下意識反應是英文", lit: "即時英語反應", fast: "Instant reaction [/ˈɪnstənt riˈækʃn/]", note: "被踩到腳脫口而出 Ouch! 或 My bad!。", q: "How do you know that English has genuinely become intuitive for you?", cefr: "B1" },
      { text: "English as second nature", sit: "讓英文融入血液，成為個人的第二本能", lit: "英語如同第二自然", fast: "Second nature [/ˈsekənd ˈneɪtʃər/]", note: "宛如騎自行車般的肌肉本能記憶。", q: "Do you still have to consciously think about tongue placement for 'th'?", cefr: "B1" }
    ],

    // Day 89: 讚揚極致與高度肯定 (You Nailed It & Excellence)
    89: [
      { text: "You nailed it completely!", sit: "你做得太棒了！完全答對！大獲成功！(超高頻讚嘆)", lit: "你釘死了它完全地！", fast: "Nailed it completely! [/neɪld ɪt kəmˈpliːtli/]", note: "給予同伴最振奮人心、無可挑剔的極致讚揚。", q: "How did my blind quiz performance look to you today?", cefr: "A2" },
      { text: "Hit the sweet spot.", sit: "恰到好處！打中了最完美的甜蜜平衡點！", lit: "擊打那甜點", fast: "Hit the sweet spot [/hɪt ðə swiːt spɑːt/]", note: "源自網球棒球球拍最完美的擊球甜蜜點。", q: "How is the volume and playback speed on this shadowing audio clip?", cefr: "B1" },
      { text: "Second to none!", sit: "首屈一指！獨一無二，無人能出其右！", lit: "第二對沒有人！", fast: "Second to none! [/ˈsekənd tə nʌn/]", note: "最高等級的品質肯定。", q: "What do you think of this Italian restaurant's handmade pasta?", cefr: "B1" },
      { text: "Beyond all expectations!", sit: "遠遠超出所有人原先預期的水準！太驚艷了！", lit: "超越所有期望！", fast: "Beyond expectations! [/bɪˈjɑːnd ˌekspekˈteɪʃnz/]", note: "令人刮目相看時的讚美。", q: "She went from beginner to fluent English speaker in just 90 days!", cefr: "B1" },
      { text: "Outstanding job done!", sit: "極為傑出優秀的完美表現！", lit: "傑出工作被做！", fast: "Outstanding job! [/aʊtˈstændɪŋ dʒɑːb/]", note: "對他人辛苦付出給予最高的敬重肯定。", q: "Our team finished the entire 100-day curriculum revamp today!", cefr: "A2" },
      { text: "Top-notch performance", sit: "頂級一流的高水準發揮與演出！", lit: "頂級缺口表現", fast: "Top-notch [/tɑːp nɑːtʃ pərˈfɔːrməns/]", note: "top-notch 是美語中代表最高品質的口語詞彙。", q: "How was the violinist's solo performance at the concert hall?", cefr: "B1" },
      { text: "Take a bow!", sit: "向全場致謝謝幕吧！你值得全體起立熱烈鼓掌！", lit: "拿取一個鞠躬！", fast: "Take a bow! [/teɪk ə baʊ/]", note: "bow 在此發音為 /baʊ/（鞠躬）。", q: "You memorized all 900 chunks and answered every question right!", cefr: "B1" },
      { text: "Master of your craft", sit: "你真是這個專業領域的頂尖大師！", lit: "大師之你的工藝", fast: "Master of yer craft [/ˈmæstər əv jər kræft/]", note: "讚美他人爐火純青的深厚造詣。", q: "Look at how smoothly that barista pours latte art with one hand!", cefr: "B1" },
      { text: "Bravo on your success!", sit: "為你的巨大成功喝采喝彩！太精彩了！", lit: "喝采在你的成功上！", fast: "Bravo! [/ˈbrɑːvoʊ ɑːn jər səkˈses/]", note: "源自義大利語的國際通用熱烈喝采詞。", q: "I just got accepted into the master's program at Oxford University!", cefr: "B1" },
      { text: "Pure perfection!", sit: "簡直純粹的完美無瑕！無可挑剔！", lit: "純粹完美！", fast: "Pure perfection! [/pjʊr pərˈfekʃn/]", note: "形容藝術品或極致體驗的讚嘆詞。", q: "How did that warm apple cinnamon pie taste with vanilla ice cream?", cefr: "A2" }
    ],

    // Day 90: 放下完美主義的心態 (Progress Over Perfection - 1314 靈魂信條)
    90: [
      { text: "Progress over perfection.", sit: "每天看重實質進步，勝過追求病態完美 (1314 核心靈魂信條)", lit: "進步在完美之上", fast: "Progress over perfection [/ˈprɑːɡres ˈoʊvər/]", note: "放下對完美的病態執念，敢開口講就是巨大勝利。", q: "I always get anxious that my English accent isn't identical to a Californian!", cefr: "B1" },
      { text: "Done is better than perfect.", sit: "先求完成，再求完美！動手做才是王道 (矽谷名言)", lit: "被完成的是更好比起完美的", fast: "Done is better than perfect [/dʌn ɪz ˈbetər ðən/]", note: "擊碎拖延與自我內耗的最強格言。", q: "Should I wait until I know all 1000 chunks before speaking to foreigners?", cefr: "B1" },
      { text: "Be kind to yourself.", sit: "對自己溫柔寬容一點，別苛責挑剔自己", lit: "是仁慈的對你自己", fast: "Be kind ta yerself [/biː kaɪnd tə jərˈself/]", note: "在學習遇到撞牆期時擁抱自己。", q: "I feel so discouraged because I forgot two words during my speech.", cefr: "A2" },
      { text: "Don't overthink it.", sit: "別再胡思亂想過度內耗了！放輕鬆！", lit: "不要過度思考它", fast: "Don't overthink it [/doʊnt ˌoʊvərˈθɪŋk ɪt/]", note: "overthink it 連讀為 /ˌoʊ.vərˈθɪŋ.kɪt/。", q: "What if the waiter thinks my coffee order sounds grammatically strange?", cefr: "A2" },
      { text: "Trust the daily process.", sit: "相信每天累積微小努力的神奇過程 (1314 堅持心法)", lit: "信任每日過程", fast: "Trust the process [/trʌst ðə ˈprɑːses/]", note: "時間看得見每一天的付出，水滴終將石穿。", q: "I don't see massive overnight changes in my English speaking fluency.", cefr: "B1" },
      { text: "Embrace your mistakes.", sit: "坦然張開雙臂擁抱每一個口語小失誤", lit: "擁抱你的錯誤", fast: "Embrace yer mistakes [/ɪmˈbreɪs jər mɪˈsteɪks/]", note: "每一次犯錯都是大腦神經元重新校準的黃金機會。", q: "Why shouldn't I feel embarrassed when I use the wrong verb tense?", cefr: "B1" },
      { text: "Good enough to ship.", sit: "已經足夠優秀了，大膽推出去吧！別再猶豫了！", lit: "足夠好去船運", fast: "Good enough to ship [/ɡʊd ɪˈnʌf tə ʃɪp/]", note: "告別吹毛求疵的完美主義枷鎖。", q: "Is this travel blog post ready to be published on the website?", cefr: "B1" },
      { text: "Drop the inner critic.", sit: "放下內心那個挑剔刻薄的自我批判聲音", lit: "掉落內在批評家", fast: "Drop the inner critic [/drɑːp ðə ˈɪnər ˈkrɪtɪk/]", note: "學會給予自己無條件的接納與支持。", q: "There's a voice inside my head constantly telling me my English isn't good enough.", cefr: "B1" },
      { text: "Courage over accuracy", sit: "敢於開口的勇氣，重要性遠勝過教科書死板的精確性", lit: "勇氣在精確性之上", fast: "Courage over accuracy [/ˈkɜːrɪdʒ ˈoʊvər/]", note: "溝通的本質在於心靈共鳴，而非文法考試滿分。", q: "What trait makes language learners achieve conversational fluency fastest?", cefr: "B1" },
      { text: "Gentle self-compassion", sit: "帶著溫柔慈悲的心態與自己和解、攜手前行", lit: "溫柔自我同情", fast: "Self-compassion [/ˌself kəmˈpæʃn/]", note: "compassion 重音在第二音節 /kəmˈpæʃn/。", q: "How do you maintain a happy, peaceful mindset during challenging times?", cefr: "B1" }
    ],

    // Day 91: 跨文化對話的包容與幽默 (Humor & Cultural Openness)
    91: [
      { text: "A pinch of humor", sit: "生活與對話中少不了一絲幽默感潤滑", lit: "一撮之幽默", fast: "Pinch of humor [/pɪntʃ əv ˈhjuːmər/]", note: "pinch of 連音為 /ˈpɪn.tʃəv/，幽默能化解所有文化隔閡。", q: "What's the best way to diffuse tension during an awkward silence?", cefr: "B1" },
      { text: "Cultural differences", sit: "文化差異是豐富人生的美妙禮物，值得欣賞", lit: "文化差異", fast: "Cultural differences [/ˈkʌltʃərəl ˈdɪfrənsɪz/]", note: "尊重不同背景的世界觀。", q: "Why do British and American people have different senses of humor?", cefr: "A2" },
      { text: "Open mind, open heart", sit: "保持開放的胸襟與包容接納的心靈", lit: "打開的心智，打開的心臟", fast: "Open mind, open heart [/ˈoʊpən maɪnd ˈoʊpən hɑːrt/]", note: "擁抱多元世界最美好的生活姿態。", q: "How should a traveler approach unfamiliar food and customs overseas?", cefr: "A2" },
      { text: "Laugh together heartily.", sit: "大家開懷大笑在一起，瞬間拉近距離", lit: "笑在一起由衷地", fast: "Laugh together [/læf təˈɡeðər ˈhɑːrtɪli/]", note: "笑聲是無須翻譯的世界共通語言。", q: "What happened when both of you realized you were mispronouncing each other's names?", cefr: "B1" },
      { text: "Universal body language", sit: "真誠的微笑是全世界最共通的萬能語言", lit: "普遍身體語言", fast: "Body language [/ˈbɑːdi ˈlæŋɡwɪdʒ/]", note: "眼神接觸與微笑能跨越所有詞彙障礙。", q: "How did you manage to buy fresh fruit in a rural Italian village?", cefr: "A2" },
      { text: "Learn other perspectives.", sit: "謙虛聆聽學習不同的世界視角與人生觀點", lit: "學習其他視角", fast: "Other perspectives [/ˈʌðər pərˈspektɪvz/]", note: "走出狹隘思維圈，看見更廣闊的天空。", q: "Why is talking to international backpackers so intellectually stimulating?", cefr: "B1" },
      { text: "Bridge the cultural gap.", sit: "搭建起跨越文化鴻溝的溫暖友誼橋樑", lit: "橋樑那文化缺口", fast: "Bridge the gap [/brɪdʒ ðə ɡæp/]", note: "語言是人與人深度連結的最佳工具。", q: "How did our community festival bring local and foreign residents closer?", cefr: "B1" },
      { text: "No prejudice, just curiosity.", sit: "心中毫無偏見成見，只有滿滿的求知好奇心", lit: "沒有偏見，剛好好奇", fast: "Just curiosity [/dʒʌst ˌkjʊriˈɑːsəti/]", note: "好奇心取代批判心態。", q: "What attitude helps you make friends with people from all walks of life?", cefr: "B1" },
      { text: "Share warm food and stories.", sit: "圍坐在一起分享熱騰騰的美食與人生故事", lit: "分享溫暖食物且故事", fast: "Food and stories [/fuːd ən ˈstɔːriz/]", note: "人類自古以來建立深厚情誼的最溫暖儀式。", q: "What was the highlight of your homestay in Vancouver?", cefr: "A2" },
      { text: "Global citizen mindset", sit: "具備放眼全球的世界公民寬廣胸襟與視野", lit: "全球公民心智設定", fast: "Global citizen [/ˈɡloʊbl ˈsɪtɪzn ˈmaɪndset/]", note: "不被地理疆界局限的宏觀思考。", q: "How has mastering English changed the way you view world news?", cefr: "B1" }
    ],

    // Day 92: 運動與生活地道隱喻 (Everyday Idioms & Metaphors)
    92: [
      { text: "Hit a home run!", sit: "打出一記精彩絕倫的全壘打！大獲全勝！", lit: "擊打一個家庭奔跑！", fast: "Home run! [/hoʊm rʌn/]", note: "美語中最深入人心的棒球成功隱喻。", q: "Did your new product launch achieve the sales target?", cefr: "A2" },
      { text: "Ball is in your court.", sit: "現在球在你的半場了 / 輪到你表態做決定了", lit: "球是在你的球場", fast: "Ball's in yer court [/bɔːlz ɪn jər kɔːrt/]", note: "源自網球：該輪到對方回球出招了。", q: "I sent them my final salary proposal, what happens next?", cefr: "B1" },
      { text: "Slam dunk!", sit: "灌籃得分！板上釘釘、十拿九穩的穩贏事情！", lit: "重摔灌籃！", fast: "Slam dunk! [/slæm dʌŋk/]", note: "源自籃球灌籃，形容萬無一失的勝利。", q: "Do you think the council will approve our park cleanup proposal?", cefr: "B1" },
      { text: "Touch base with you.", sit: "跟你碰個頭簡單對一下進度 (極高頻生活片語)", lit: "觸摸壘包與你", fast: "Touch base with ya [/tʌtʃ beɪs wɪð jə/]", note: "美式棒球源流，日常溝通交流必備。", q: "When can we quickly align on the weekend road trip route?", cefr: "B1" },
      { text: "Game changer", sit: "顛覆既有規則的革命性重大改變！", lit: "遊戲改變者", fast: "Game changer [/ɡeɪm ˈtʃeɪndʒər/]", note: "徹底改變局面的人事物。", q: "How did discovering English Podcast 1314 affect your learning routine?", cefr: "A2" },
      { text: "Keep eye on the ball.", sit: "把眼睛全神貫注盯在球上 / 專注核心目標不分心", lit: "保持眼睛在那球上", fast: "Eye on the ball [/aɪ ɑːn ðə bɔːl/]", note: "提醒同伴保持專注、莫忘初衷。", q: "There are so many distracting side projects competing for our attention!", cefr: "B1" },
      { text: "Drop the ball", sit: "把球給漏接弄掉了 / 一時疏忽搞砸了失職", lit: "掉落那球", fast: "Drop the ball [/drɑːp ðə bɔːl/]", note: "坦承自己漏掉關鍵細節時說。", q: "I'm so sorry, I completely forgot to confirm our table reservation!", cefr: "B1" },
      { text: "Jump the gun", sit: "搶跑偷跑 / 操之過急、為時過早輕舉妄動", lit: "跳躍那槍", fast: "Jump the gun [/dʒʌmp ðə ɡʌn/]", note: "源自田徑賽選手在發令槍響前搶跑。", q: "Should we announce our engagement before telling our families?", cefr: "B1" },
      { text: "Level playing field", sit: "營造一個公平競爭、起跑線平等的遊戲環境", lit: "平水準的遊戲場地", fast: "Level playing field [/ˈlevl ˈpleɪɪŋ fiːld/]", note: "公平無偏見的體制。", q: "Why should education resources be accessible to every child freely?", cefr: "B1" },
      { text: "Throw in the towel", sit: "扔白毛巾認輸 / 徹底棄權投降放棄", lit: "扔進那毛巾", fast: "Throw in the towel [/θroʊ ɪn ðə ˈtaʊəl/]", note: "源自拳擊教練向擂台扔毛巾認輸的典故。", q: "After struggling for two hours with the flat tire, did you call roadside assistance?", cefr: "B1" }
    ],

    // Day 93: 美食、咖啡與生活儀式感 (1314 咖啡與生活儀式)
    93: [
      { text: "A cup of pure joy", sit: "早晨那一杯純粹帶來幸福感的溫熱咖啡 (1314 生活儀式)", lit: "一杯純粹樂趣", fast: "Cup of joy [/kʌp əv dʒɔɪ/]", note: "cup of 連音為 /ˈkʌ.pəv/，開啟美好一天的儀式。", q: "What's the very best part of your quiet morning routine?", cefr: "A2" },
      { text: "Savor the rich flavor.", sit: "慢下腳步，細細品味層次豐富的香醇滋味", lit: "品嚐那豐富風味", fast: "Savor the flavor [/ˈseɪvər ðə ˈfleɪvər/]", note: "savor 表示全心沉浸享受美食當下。", q: "How do you enjoy this single-origin pour-over Ethiopian roast?", cefr: "B1" },
      { text: "Little daily ritual", sit: "每天不可或缺、滋養心靈的神聖生活小儀式感", lit: "小每日儀式", fast: "Daily ritual [/ˈdeɪli ˈrɪtʃuəl/]", note: "點香氛蠟燭、泡熱茶或早晨閱讀 10 分鐘。", q: "Why do small habits bring so much emotional stability to your life?", cefr: "B1" },
      { text: "Feel warm and cozy.", sit: "整個人感覺無比溫暖而舒適愜意放鬆", lit: "感覺溫暖且舒適", fast: "Warm an' cozy [/wɔːrm ən ˈkoʊzi/]", note: "秋冬裹著毛毯喝熱可可時的幸福寫照。", q: "How does it feel sitting by the fireplace watching rain fall outside?", cefr: "A2" },
      { text: "Comfort food for soul", sit: "撫慰疲憊心靈的療癒系私房溫暖美食", lit: "舒適食物為了靈魂", fast: "Comfort food [/ˈkʌmfərt fuːd fər soʊl/]", note: "一碗熱騰騰的雞湯麵或香濃咖哩飯。", q: "What do you crave after walking home in the freezing cold rain?", cefr: "A2" },
      { text: "Brew with loving care.", sit: "帶著愛心與專注，用心手沖每一滴香醇咖啡", lit: "釀造帶著愛的照顧", fast: "Brew with care [/bruː wɪð ker/]", note: "專注過程本身就是一種舒壓冥想。", q: "Why do you grind your own beans by hand every morning?", cefr: "B1" },
      { text: "Quiet morning moment", sit: "清晨專屬於自己一個人獨處的靜謐時光", lit: "安靜早晨時刻", fast: "Quiet morning [/ˈkwaɪət ˈmɔːrnɪŋ ˈmoʊmənt/]", note: "在世界醒來前與自己溫柔對話。", q: "What is your secret to staying grounded and calm during hectic days?", cefr: "A2" },
      { text: "Candlelit evening vibe", sit: "點起香氛蠟燭、平靜放鬆的晚間浪漫氛圍", lit: "燭光夜晚氛圍", fast: "Candlelit vibe [/ˈkændllɪt vaɪb/]", note: "vibe 表示氣氛、格調、情調。", q: "How do you set the mood for reading before going to sleep?", cefr: "B1" },
      { text: "Treat myself well.", sit: "在忙碌奔波之餘，好好善待犒賞一下自己", lit: "對待我自己好", fast: "Treat myself well [/triːt maɪˈself wel/]", note: "吃一頓精緻甜點或泡熱水澡放鬆身心。", q: "You've worked fifty hours this week, what are you doing this Sunday?", cefr: "A2" },
      { text: "Simple pleasures of life", sit: "生活中最平凡微小、卻最深刻純粹的日常樂趣", lit: "簡單樂趣之生命", fast: "Simple pleasures [/ˈsɪmpl ˈpleʒərz əv laɪf/]", note: "生活中的陽光微風與好友歡笑。", q: "What brings you genuine happiness that doesn't cost a single dime?", cefr: "B1" }
    ],

    // Day 94: 人生目標與熱情所在 (Passion, Purpose & Dreams)
    94: [
      { text: "Follow your true heart.", sit: "勇敢傾聽並追隨你內心深處最真實的聲音", lit: "跟隨你的真實心臟", fast: "Follow yer heart [/ˈfɑːloʊ jər hɑːrt/]", note: "不盲從他人眼光與世俗期待。", q: "How did you decide to leave corporate finance to open a bakery?", cefr: "A2" },
      { text: "Find your inner passion.", sit: "找尋能讓你靈魂燃燒、忘卻時間的真正熱情所在", lit: "找到你的內在熱情", fast: "Inner passion [/ˈɪnər ˈpæʃn/]", note: "熱情是讓人不知疲倦奔跑的引擎。", q: "What activity makes you completely lose track of time when doing it?", cefr: "B1" },
      { text: "What drives you forward?", sit: "到底是什麼信念力量在驅使你每天前進？", lit: "什麼驅動你向前？", fast: "What drives ya? [/wʌt draɪvz jə ˈfɔːrwərd/]", note: "探尋人生的底層動力源泉。", q: "You wake up energized at 6 AM every day. What drives you forward?", cefr: "B1" },
      { text: "Dream big, start small.", sit: "懷抱遠大的夢想，但從手邊腳踏實地的小事開始做起", lit: "夢想大，開始小", fast: "Dream big, start small [/driːm bɪɡ stɑːrt smɔːl/]", note: "1314 最推崇的目標實踐哲學。", q: "How did you manage to build this massive 100-day English study program?", cefr: "A2" },
      { text: "Live a meaningful life.", sit: "過著內心感到充實、有意義、不虛度的人生", lit: "生活一個有意義的生命", fast: "Meaningful life [/ˈmiːnɪŋfl laɪf/]", note: "追求深層價值感而非浮名虛譽。", q: "What is your ultimate definition of a life well-lived?", cefr: "B1" },
      { text: "Make a positive impact.", sit: "為身邊的人與世界帶來溫暖正向的改變與影響", lit: "製造一個積極衝擊", fast: "Positive impact [/ˈpɑːzətɪv ˈɪmpækt/]", note: "用自己的能力點亮他人的生命。", q: "Why do you volunteer at the animal shelter every other Saturday?", cefr: "B1" },
      { text: "Stay true to yourself.", sit: "永遠忠於自我本色，不盲目隨波逐流迎合他人", lit: "停留真實對你自己", fast: "Stay true ta yerself [/steɪ truː tə jərˈself/]", note: "做最真實純粹的自己，心靈最坦蕩。", q: "How do you handle pressure from society to follow a standard path?", cefr: "B1" },
      { text: "Fuel your burning fire.", sit: "為心中那團熱愛夢想的火焰不斷添加柴火", lit: "給燃料你的燃燒火焰", fast: "Fuel yer fire [/ˈfjuːəl jər ˈbɜːrnɪŋ ˈfaɪər/]", note: "持續輸入好書與啟發，讓熱情永不熄滅。", q: "What keeps your creative spark alive after all these years?", cefr: "B1" },
      { text: "Uncover your unique purpose.", sit: "發掘你降生於這個世界的獨特人生使命", lit: "揭開你的獨特目的", fast: "Unique purpose [/juˈniːk ˈpɜːrpəs/]", note: "每個人都有自己獨一無二的天賦使命。", q: "Do you believe everyone has a special calling in this life?", cefr: "B1" },
      { text: "Leave the world better.", sit: "努力讓這個世界因為你的存在而變得更好一點點", lit: "離開這世界更好", fast: "Leave the world better [/liːv ðə wɜːrld ˈbetər/]", note: "人生最崇高美好的終極期許。", q: "What legacy do you hope to leave behind for the next generation?", cefr: "B1" }
    ],

    // Day 95: 真摯感謝與深層連結 (Heartfelt Gratitude & Deep Bonds)
    95: [
      { text: "Heartfelt thanks to you.", sit: "向你致上最深沉真摯由衷的感激與謝意", lit: "心感受的感謝對你", fast: "Heartfelt thanks [/ˈhɑːrtfelt θæŋks/]", note: "比口頭謝謝厚重十倍的真情流露。", q: "Thank you for supporting my dreams through thick and thin.", cefr: "B1" },
      { text: "From bottom of my heart", sit: "發自我的內心最深處 / 掏心掏肺 (至深感激)", lit: "從我的心臟的底部", fast: "From bottom of my heart [/frəm ˈbɑːtəm əv maɪ hɑːrt/]", note: "表達深沉人際連結時最感人的短成語。", q: "I genuinely could not have achieved this milestone without your guidance.", cefr: "B1" },
      { text: "Forever grateful to you.", sit: "我將永遠感念並銘記你的這份恩情與幫助", lit: "永遠感激的對你", fast: "Forever grateful [/fərˈevər ˈɡreɪtfʊl/]", note: "一生感念在心的承諾。", q: "You gave me a chance when no other company would even look at my resume.", cefr: "B1" },
      { text: "Truly appreciate your presence.", sit: "無比感謝你的陪伴出現在我的生命旅途當中", lit: "真實感激你的存在", fast: "Appreciate yer presence [/əˈpriːʃieɪt jər ˈprezns/]", note: "向人生導師或伴侶表達深層愛意的金句。", q: "Having you as a study partner made these 100 days so joyous and fun.", cefr: "B1" },
      { text: "Touched my heart deeply.", sit: "你的這份善意深深觸動了我內心最柔軟的角落", lit: "觸摸了我的心臟深深地", fast: "Touched my heart [/tʌtʃt maɪ hɑːrt ˈdiːpli/]", note: "touched 發音為 /tʌtʃt/。", q: "The whole community chipped in to help rebuild the neighborhood playground!", cefr: "B1" },
      { text: "Words cannot express it.", sit: "千言萬語都難以完全表達我心中的感激與感動", lit: "字不能表達它", fast: "Words can't express it [/wɜːrdz kænt ɪkˈspres ɪt/]", note: "感動到熱淚盈眶時說。", q: "Look at all the surprise birthday letters your students wrote for you!", cefr: "B1" },
      { text: "Blessed to know you.", sit: "這輩子能遇見認識你是我莫大的福氣與幸運！", lit: "被祝福去知道你", fast: "Blessed ta know ya [/blest tə noʊ jə/]", note: "向摯友表達相識之緣的最高禮讚。", q: "Thank you for ten years of unconditional laughter, kindness, and support.", cefr: "A2" },
      { text: "Thank you for believing in me.", sit: "謝謝你在全世界都懷疑我時，依然堅定相信我", lit: "謝謝你為了相信在我裡面", fast: "Thanks fer believin' in me [/θæŋks fər bɪˈliːvɪn ɪn miː/]", note: "最催淚深沉的感謝話語。", q: "Even when I failed my exam, you told me I would make a great doctor.", cefr: "A2" },
      { text: "Made a lasting difference.", sit: "你的出現為我的人生帶來了深遠而持久的改變", lit: "製造了一個持久的差異", fast: "Lasting difference [/ˈlæstɪŋ ˈdɪfrəns/]", note: "肯定他人生命的深遠價值。", q: "How did learning with this shadowing program transform your mindset?", cefr: "B1" },
      { text: "Bound by genuine love.", sit: "彼此的心緊緊被真摯的愛與善意連結在一起", lit: "被捆綁由真正愛", fast: "Bound by love [/baʊnd baɪ ˈdʒenjuɪn lʌv/]", note: "人與人之間最神聖無暇的靈魂羈絆。", q: "What keeps our family so close across three different continents?", cefr: "B1" }
    ],

    // Day 96: 【衝刺日 1】生活高頻 100 塊盲聽盲答 (Fluency Sprint 1)
    96: [
      { text: "Fast reflex response", sit: "【巔峰衝刺】神經反射極速回答，0.3 秒無秒差開口！", lit: "快速反射反應", fast: "Fast reflex [/fæst ˈriːfleks/]", note: "徹底擺脫思維停頓，肌肉記憶主動輸出。", q: "Hey! How's your week been treating you?", cefr: "B1" },
      { text: "Zero hesitation speaking", sit: "開口說話毫無半點猶豫遲疑，脫口而出", lit: "零猶豫說話", fast: "Zero hesitation [/ˈzɪroʊ ˌhezɪˈteɪʃn/]", note: "自信滿滿，流暢自如。", q: "Are you ready to order lunch right now?", cefr: "B1" },
      { text: "Instant recall memory", sit: "瞬間調取腦海記憶語塊，隨抓隨用", lit: "即時召回記憶", fast: "Instant recall [/ˈɪnstənt rɪˈkɔːl/]", note: "千塊語塊庫如同口袋樂高積木隨時拼裝。", q: "What should we say when we need to politely interrupt someone?", cefr: "B1" },
      { text: "Clear and crisp voice", sit: "發音咬字清晰乾脆、字字動聽有穿透力", lit: "清晰且脆的聲音", fast: "Clear an' crisp [/klɪr ən krɪsp/]", note: "聲帶共鳴充分，氣流充沛。", q: "How does your recorded voice sound during today's shadowing playback?", cefr: "B1" },
      { text: "Total immersion focus", sit: "全神貫注完全沉浸在純英語語境氛圍中", lit: "完全沉浸聚焦", fast: "Immersion focus [/ɪˈmɜːrʒn ˈfoʊkəs/]", note: "心無旁騖，大腦全開。", q: "Can you think and react in English for twenty minutes nonstop?", cefr: "B1" },
      { text: "Listen with acute sharpness.", sit: "耳朵無比敏銳地捕捉每個母語連音弱化細節", lit: "聆聽帶著尖銳鋒利", fast: "Acute sharpness [/əˈkjuːt ˈʃɑːrpnəs/]", note: "連音形變在耳中如白紙黑字般清晰。", q: "Did you catch how 'What are you' blended into 'Whatcha' in that clip?", cefr: "B1" },
      { text: "Speak like a native.", sit: "說起英語如母語者般隨和流利自然自然", lit: "說話如同一個本地人", fast: "Speak like a native [/spiːk laɪk ə ˈneɪtɪv/]", note: "充滿母語人士般的鬆弛感與節奏感。", q: "How did foreign tourists react to your directions on the subway today?", cefr: "B1" },
      { text: "Speed doesn't scare me.", sit: "再快的英語原速對話也絲毫嚇不到我！", lit: "速度不做嚇唬我", fast: "Speed doesn't scare me [/spiːd ˈdʌznt sker miː/]", note: "建立了強大的聽力自信心與安全感。", q: "Do you still feel panic when a fast-talking New Yorker speaks to you?", cefr: "A2" },
      { text: "100 chunks blitzed!", sit: "一百個高頻日常口語塊盲測極速通關！", lit: "100語塊被閃擊！", fast: "100 chunks blitzed! [/wʌn ˈhʌndrəd tʃʌŋks blɪtst/]", note: "第一衝刺日圓滿拿下！", q: "Congratulations on blitzing through all one hundred speed-drill chunks!", cefr: "A2" },
      { text: "Sharp mind, quick tongue", sit: "思維敏銳俐落，舌頭髮音靈巧無比", lit: "鋒利心智，快速舌頭", fast: "Quick tongue [/kwɪk tʌŋ/]", note: "身心合一，達到語言運動員的絕佳競技狀態。", q: "How would you describe your mental alertness after this sprint?", cefr: "B1" }
    ],

    // Day 97: 【衝刺日 2】卡頓語塊徹底消除 (Fluency Sprint 2: Zero Stutter)
    97: [
      { text: "Smooth effortless fluency", sit: "【巔峰衝刺】如絲綢般順滑不費力的極致流利度", lit: "平滑不費力流利", fast: "Effortless fluency [/ˈefərtləs ˈfluːənsi/]", note: "不再死記硬背，語意隨心流淌。", q: "How does your mouth feel when transitioning between chunks today?", cefr: "B1" },
      { text: "No more stuttering pauses.", sit: "再也沒有任何結巴、重複或尷尬停頓", lit: "沒有更多口吃暫停", fast: "No more pauses [/noʊ mɔːr ˈpɔːzɪz/]", note: "徹底告別呃...啊...等中式卡頓詞。", q: "Do you still freeze up when looking for a word in the middle of a thought?", cefr: "B1" },
      { text: "Flowing uninterrupted speech", sit: "綿延不絕、行雲流水的連續發音", lit: "流動不被打斷的演講", fast: "Flowing speech [/ˈfloʊɪŋ spiːtʃ/]", note: "以塊為單位呼吸輸出，節奏感極佳。", q: "Can you speak for two minutes straight using five connected chunks?", cefr: "B1" },
      { text: "Unlocked vocal freedom", sit: "喉嚨與聲帶徹底解鎖，開口自由無拘無束", lit: "被解鎖的聲音自由", fast: "Vocal freedom [/ˈvoʊkl ˈfriːdəm/]", note: "克服心魔後的豁然開朗境地。", q: "How does it feel to speak English without that heavy lump in your throat?", cefr: "B1" },
      { text: "Freedom of spoken expression", sit: "口語表達達到隨心所欲、暢所欲言的自在境界", lit: "自由之口語表達", fast: "Spoken expression [/ˈspoʊkən ɪkˈspreʃn/]", note: "掌握了溝通的主控權與選擇權。", q: "What's the best part of having a rich personal chunk dictionary?", cefr: "B1" },
      { text: "Banish conversational fear.", sit: "把過去對開口的所有恐懼徹底驅逐出境", lit: "放逐對話恐懼", fast: "Banish fear [/ˈbænɪʃ fɪr/]", note: "恐懼化作歷史塵埃，心中只有自信從容。", q: "Do you remember how scared you felt on Day 1 of this program?", cefr: "B1" },
      { text: "Speak in long breath units.", sit: "以完整的意群語塊為一呼一吸的發音節奏單位", lit: "說話在長呼吸單位", fast: "Breath units [/breθ ˈjuːnɪts/]", note: "母語人士的呼吸換氣法門。", q: "Why is breathing between chunks so much more natural than between words?", cefr: "B1" },
      { text: "Melodic English intonation", sit: "語調富有如音樂般的抑揚頓挫優美旋律", lit: "旋律的英語語調", fast: "Melodic intonation [/məˈlɑːdɪk ˌɪntəˈneɪʃn/]", note: "像唱歌般感受美語重音與弱音的律動。", q: "How do your sentences sound when you focus on sentence stress?", cefr: "B1" },
      { text: "Confident rhythm", sit: "對話節奏沉著自信，從容不迫掌控全場氣氛", lit: "自信節奏", fast: "Confident rhythm [/ˈkɑːnfɪdənt ˈrɪðəm/]", note: "不慌亂搶話，淡定掌控發言權。", q: "How do colleagues perceive your meeting participation now?", cefr: "B1" },
      { text: "Zero hesitation achieved!", sit: "達成零猶豫零卡頓的傲人里程碑突破！", lit: "零猶豫被達成！", fast: "Zero hesitation! [/ˈzɪroʊ ˌhezɪˈteɪʃn/]", note: "第二衝刺日完美過關！", q: "Congratulations! You have eliminated conversational stutter completely!", cefr: "B1" }
    ],

    // Day 98: 【衝刺日 3】全隨機速度 1.25x 輕鬆跟讀 (Fluency Sprint 3: Fast Shadowing)
    98: [
      { text: "High speed shadowing mastery", sit: "【巔峰衝刺】1.25 倍原速盲聽跟讀輕鬆駕馭！", lit: "高速度影子大師", fast: "High speed shadowing [/haɪ spiːd ˈʃædoʊɪŋ/]", note: "耳朵和口腔肌肉適應超高速後，看正常速度如慢鏡頭。", q: "Can you comfortably shadow native audio at 1.25x playback speed?", cefr: "B1" },
      { text: "Sharp attuned ears", sit: "耳朵訓練得無比敏銳，任何吞音連音逃不出耳朵", lit: "鋒利調準的耳朵", fast: "Attuned ears [/əˈtuːnd ɪrz/]", note: "聽力辨識度達到前所未有的高清境界。", q: "Why do movies and TV shows sound so crystal clear to you now?", cefr: "B1" },
      { text: "Agile and nimble tongue", sit: "舌頭敏捷靈巧，跟隨母語原速節拍同步起舞", lit: "敏捷且靈活舌頭", fast: "Nimble tongue [/ˈnɪmbl tʌŋ/]", note: "舌頭肌肉發達，發音轉換行雲流水。", q: "How does your mouth feel during high-speed dialogue drills?", cefr: "B1" },
      { text: "On the fast track", sit: "行駛在大師級流利的超高速快車道上奔馳", lit: "在快軌道上", fast: "Fast track [/fæst træk/]", note: "進步速度一日千里。", q: "How would you describe your transformation over the past three months?", cefr: "A2" },
      { text: "Effortless comprehension", sit: "毫不費力完全領會原汁原味的英語廣播播客", lit: "不費力理解", fast: "Effortless comprehension [/ˈefərtləs ˌkɑːmprɪˈhenʃn/]", note: "聽懂英語如同呼吸空氣般自然。", q: "Do you still have to strain your brain when listening to English podcasts?", cefr: "B1" },
      { text: "Process speed doubled", sit: "大腦意象處理反應速度瞬間翻倍升級！", lit: "過程速度被翻倍", fast: "Speed doubled [/spiːd ˈdʌbld/]", note: "神經迴路超導化，毫無延遲卡頓。", q: "How fast do your thoughts turn into spoken English phrases now?", cefr: "B1" },
      { text: "Catch every subtle nuance.", sit: "精準捕捉母語人士每一絲微妙的語氣情感轉折", lit: "抓住每個微妙細微差別", fast: "Subtle nuance [/ˈsʌtl ˈnuːɑːns/]", note: "聽出話外之音、幽默諷刺與真心關切。", q: "Can you tell when a speaker is being genuinely sincere versus polite?", cefr: "B1" },
      { text: "Sync voice with audio.", sit: "自己的發音與原音檔完美同頻共振、合而為一", lit: "同步聲音與音訊", fast: "Sync voice [/sɪŋk vɔɪs/]", note: "跟讀時差精確壓縮到零點幾秒。", q: "Does your shadowing sound like a seamless stereo duet with the speaker?", cefr: "B1" },
      { text: "Trained for high velocity", sit: "經歷超高速特訓後，回頭聽正常語速慢如散步", lit: "被訓練為了高速率", fast: "High velocity [/haɪ vəˈlɑːsəti/]", note: "重訓加重後放下的極致輕盈感。", q: "How does 1.0x normal speed audio sound to your trained ears now?", cefr: "B1" },
      { text: "Peak athletic performance", sit: "達到語言神經反射運動員般的頂峰競技狀態", lit: "峰頂運動表現", fast: "Peak performance [/piːk pərˈfɔːrməns/]", note: "第三衝刺日超高速考驗圓滿告捷！", q: "Congratulations! You have conquered the highest-speed shadowing challenge!", cefr: "B1" }
    ],

    // Day 99: 【衝刺日 4】15 分鐘全英語自由對話 (Fluency Sprint 4: Nonstop Free Speech)
    99: [
      { text: "Nonstop English expression", sit: "【巔峰衝刺】十五分鐘全英語沉浸式不間斷自由表達！", lit: "不停止英語表達", fast: "Nonstop expression [/ˌnɑːnˈstɑːp ɪkˈspreʃn/]", note: "全程零中文，滔滔不絕分享個人觀點。", q: "Can you speak in English about your favorite hobby for 15 minutes straight?", cefr: "B1" },
      { text: "Confident everyday speaker", sit: "成為真正自信成熟、談笑風生的國際交流者", lit: "自信每日說話者", fast: "Everyday speaker [/ˈevrideɪ ˈspiːkər/]", note: "任何社交場合落落大方，魅力四射。", q: "How do you carry yourself when entering an international coffee lounge?", cefr: "B1" },
      { text: "Rich vocabulary in action", sit: "生活化豐富詞彙語塊隨時在手，信手拈來隨時輸出", lit: "豐富詞彙在行動", fast: "Vocabulary in action [/vəˈkæbjəleri/]", note: "積累的語塊在真實情境中活靈活現活用。", q: "How many authentic chunks can you naturally weave into one conversation?", cefr: "B1" },
      { text: "Pure intuitive flow", sit: "純粹憑藉直覺流動發聲，不用大腦分析文法規則", lit: "純粹直覺流動", fast: "Intuitive flow [/ɪnˈtuːɪtɪv floʊ/]", note: "母語直覺的終極體現：隨心而動。", q: "What does it feel like to talk without checking grammar rules in your head?", cefr: "B1" },
      { text: "Natural relaxed accent", sit: "發音自然放鬆，展現令人著迷的鬆弛感與親和力", lit: "自然放鬆口音", fast: "Relaxed accent [/rɪˈlækst ˈæksent/]", note: "不刻意模仿假腔調，乾淨舒適大氣。", q: "How do listeners describe the overall vibe of your English speech?", cefr: "B1" },
      { text: "Hold a lively conversation.", sit: "從容主導並推進一場熱情生動的雙向生活對話", lit: "握住一個生動對話", fast: "Lively conversation [/ˈlaɪvli ˌkɑːnvərˈseɪʃn/]", note: "懂得拋球、接球、傾聽與反饋。", q: "How do you keep a casual chat rolling smoothly without awkward pauses?", cefr: "B1" },
      { text: "Paraphrase around any gap.", sit: "遇到生僻單字能用簡單語塊巧妙改述繞過 (高手特質)", lit: "改述周圍任何缺口", fast: "Paraphrase any gap [/ˈpærəfreɪz ˈeni ɡæp/]", note: "遇到不會的詞絕不卡住，換個方式輕鬆表達。", q: "If you forget the word for 'corkscrew', how do you describe it effortlessly?", cefr: "B1" },
      { text: "Spontaneous storyteller", sit: "能隨性生動、繪聲繪色講述生活中的精彩故事", lit: "自發的故事講述者", fast: "Spontaneous storyteller [/spɑːnˈteɪniəs ˈstɔːritelər/]", note: "用有血有肉的情感打動聽眾的心。", q: "Can you share a funny memory from your childhood completely in English?", cefr: "B1" },
      { text: "Language barrier collapsed!", sit: "心中的語言障礙高牆徹底轟然倒塌！暢通無阻！", lit: "語言障礙崩潰了！", fast: "Barrier collapsed! [/ˈbæriər kəˈlæpst/]", note: "世界在眼前豁然開朗，再無疆界隔閡。", q: "How does it feel to realize that English is no longer a scary monster?", cefr: "B1" },
      { text: "One day away from mastery!", sit: "距離千塊巔峰大滿貫只剩下最後二十四小時！", lit: "一天離開脫離大師！", fast: "One day away! [/wʌn deɪ əˈweɪ/]", note: "最後一天，迎向終身受用的歷史里程碑！", q: "Are you ready to claim your title as a 1000-Chunk English Master tomorrow?", cefr: "A2" }
    ],

    // Day 100: 【巔峰里程碑】突破 1000 塊 • 直覺英文大腦全面成形！ (Grand Finale: 1,000 Chunks Mastery)
    100: [
      { text: "1000 chunks fully unlocked!", sit: "【千塊大圓滿】整整一千個高頻地道語塊全數解鎖內化！", lit: "1000語塊完全被解鎖！", fast: "1000 chunks unlocked! [/wʌn ˈθaʊznd tʃʌŋks/]", note: "恭喜達成百年一遇的自律奇蹟！100 天 1000 塊圓滿封頂！", q: "Congratulations! You have completed all 100 days and unlocked 1,000 chunks!", cefr: "B1" },
      { text: "Intuitive English brain created!", sit: "直覺英語塊狀大腦全面成形，終身受用、永不退化！", lit: "直覺英語大腦被創造！", fast: "Intuitive brain created! [/ɪnˈtuːɪtɪv breɪn/]", note: "徹底告別單字逐字翻譯，英文思維深深扎根。", q: "How has your brain's relationship with the English language permanently changed?", cefr: "B1" },
      { text: "Proud of my 100-day journey!", sit: "為自己這一百天堅持到底的非凡毅力感到無上自豪！", lit: "驕傲之我的一百天旅程！", fast: "Proud of my journey! [/praʊd əv maɪ ˈdʒɜːrni/]", note: "這份自律是誰也奪不走的人生璀璨勳章。", q: "Look back at Day 1: Did you ever imagine you would come this far?", cefr: "A2" },
      { text: "Lifelong English learner", sit: "成為享受語言純粹樂趣的快樂終身學習者 (1314 核心精神)", lit: "終身英語學習者", fast: "Lifelong learner [/ˈlaɪflɔːŋ ˈlɜːrnər/]", note: "英語不再是折磨人的考試科目，而是探索世界的窗口。", q: "How will you continue exploring English podcasts and novels moving forward?", cefr: "B1" },
      { text: "The sky is the limit!", sit: "天高任鳥飛！世界再也沒有任何能夠阻擋你的界限！", lit: "那天空是那限制！", fast: "Sky's the limit! [/skaɪz ðə ˈlɪmɪt/]", note: "充滿無限可能性與未來的宏圖遠志。", q: "What new dreams and adventures will you pursue with your fluent English now?", cefr: "B1" },
      { text: "Mastery achieved with honors!", sit: "以無比耀眼的最高榮譽達成口語直覺大師境界！", lit: "大師境界被達成帶著榮譽！", fast: "Mastery achieved! [/ˈmæstəri əˈtʃiːvd/]", note: "實至名歸，恭喜你順利登頂！", q: "How does it feel to hold this master fluency badge in your heart?", cefr: "B1" },
      { text: "Shadowing changed my life.", sit: "影子跟讀訓練徹底改變了我與英語的終身關係 (真摯感言)", lit: "影子改變了我的生命", fast: "Shadowing changed my life [/ˈʃædoʊɪŋ tʃeɪndʒd/]", note: "嘴唇肌肉記憶與聽覺神經直連的奇蹟見證。", q: "Why would you recommend the EchoMind shadowing method to every beginner?", cefr: "B1" },
      { text: "Think, feel, and speak.", sit: "用英文思考、用英文感受、用英文自信開口表達！", lit: "思考，感覺，且說話", fast: "Think, feel, speak [/θɪŋk fiːl spiːk/]", note: "語言與靈魂合而為一，自然流露。", q: "What is the three-step formula for authentic conversational mastery?", cefr: "B1" },
      { text: "Never stop moving forward.", sit: "在自我進化的終身道路上，永遠熱淚盈眶、大步向前！", lit: "從不停止移動向前", fast: "Keep movin' forward [/kiːp ˈmuːvɪn ˈfɔːrwərd/]", note: "終點正是另一段更加壯闊航程的起點。", q: "What message would you send to someone just starting Day 1 today?", cefr: "A2" },
      { text: "A brand new confident me!", sit: "遇見一個全新、自信、自在開口說英語的嶄新自我！", lit: "一個品牌新自信的我！", fast: "Brand new me! [/brænd nuː miː/]", note: "致敬堅持到底、閃閃發光的每一個你！圓滿完結！", q: "Are you ready to walk into the world and speak English with pure confidence?", cefr: "B1" }
    ]
  };
})();
